def pub(p):
    doi = f' <span>DOI: {p["doi"]}</span>' if p.get('doi') else ''
    return f'<article class="publication" data-topic="{p["topic"]}"><div class="meta"><span class="pill">{p["kind"]}</span><span>{p["journal"]}</span><span>·</span><span>{p["date"]}</span></div><h3>{p["title"]}</h3><p>{p["desc"]}</p>{link("Read at the publisher ↗",p["url"])}{doi}</article>'

home='''<section class="hero wrap"><div><p class="eyebrow">Biblical theology & the life of the church</p><h1>Scripture forms<br>a <em>people.</em></h1><p class="lede">Research into the company God gathers, and writing for the people learning to live together in Christ.</p><div class="actions"><a class="button" href="/research/">Explore the research</a><a class="text-link" href="/resources/">Find a study resource</a></div><p class="byline">Craig R. Fredrickson<span>Independent scholar & Bible teacher</span></p></div><aside class="hero-note" aria-label="Featured publication"><div><p class="eyebrow">Recent publication</p><h2>The company.<br>The table.<br>The life we share.</h2><p class="citation">Fencing the paschal table</p><small>In die Skriflig / In Luce Verbi · 2026</small></div><a class="text-link" href="https://indieskriflig.org.za/index.php/skriflig/article/view/3323">Read the journal article ↗</a></aside></section><section class="method wrap"><p class="eyebrow">A connected inquiry</p><p>How does redemption take shape in a shared life? Habura Research brings close biblical study into conversation with the church’s fellowship, worship, and formation.</p></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">Research program</p><h2>The shape of belonging</h2></div><a class="text-link" href="/research/">Research & publications</a></div>'''
for n,title,desc,anchor in [('01','Passover & the gathered company','The meal, its participants, and the responsibilities of belonging.','passover'),('02','The Word & spiritual formation','How Scripture’s teaching shapes love, holiness, and assurance.','formation'),('03','The church & its shared life','The relation between redemption, fellowship, and communal responsibility.','church')]:
    home+=f'<a class="research-row" href="/research/#{anchor}"><span class="num">{n}</span><h3>{title}</h3><p>{desc}</p><span class="arrow" aria-hidden="true">↗</span></a>'
home+='''</section><section class="book-feature"><div class="wrap"><div><p class="eyebrow">From the writing desk</p><h2>Light Upon Light</h2><p class="book-subtitle">An Ascending Journey Through the Wisdom of 1 John</p><p>A commentary project following John’s recurring themes of light, love, truth, and assurance through careful reading, reflection, and worship.</p><a class="button" href="/books/light-upon-light/">Explore the book</a></div><div class="book-object"><div class="book-cover" aria-label="Illustrative cover for the Light Upon Light book project"><small>Formed by the Word</small><div><h3>Light<br>Upon<br>Light</h3><p>An Ascending Journey<br>Through the Wisdom<br>of 1 John</p></div><small>Craig R. Fredrickson</small><p class="cover-label">Book project · Illustrative cover</p></div></div></div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">Published writing</p><h2>Read the work</h2></div><a class="text-link" href="/research/#publications">All publications</a></div><div class="cards">'''
for p in PUBLICATIONS[1:]:home+=f'<article class="card"><p class="eyebrow">{p["journal"]}</p><h3>{p["title"]}</h3><p>{p["desc"]}</p>{link("Read the article ↗",p["url"])}</article>'
home+='''</div></section><section class="band wrap"><div><p class="eyebrow">For readers, teachers & churches</p><h2>Bring the text into the room.</h2><p>Study guides and reflection questions that help a group move from observation to discussion, faithful response, and prayer.</p></div><a class="button" href="/resources/">Explore resources</a></section>'''
page('Biblical scholarship for the life of the church','Research, published articles, book projects, and Bible teaching by Craig R. Fredrickson.',home)

body=intro('Research & publications','The people God gathers.','Studies in biblical theology, the Passover company, and the formation of the church through Scripture.')
body+='''<div class="content-grid wrap"><aside class="side-note"><p class="eyebrow">In this section</p><a href="#passover">Passover & company</a><a href="#formation">Word & formation</a><a href="#church">Life of the church</a><a href="#publications">Published work</a></aside><div class="prose"><section class="topic-section" id="passover"><p class="eyebrow">01 · Passover & company</p><h2>A meal with a gathered people.</h2><p>Passover brings deliverance into the life of a company: a lamb is provided, people gather, and participation carries responsibilities. This research asks how that scriptural and historical pattern can illuminate early Christian fellowship.</p><p>The inquiry begins with Exodus 12 and Numbers 9 and follows questions of participation, communal boundaries, and shared obligation. Proposed connections are weighed against the evidence of each passage.</p></section><section class="topic-section" id="formation"><p class="eyebrow">02 · Word & formation</p><h2>Reading that reaches the life.</h2><p>First Peter and 1 John connect truth with love, holiness, and assurance. Their exhortations call for sustained attention to how the biblical text teaches and forms its hearers.</p><p>The work brings exegesis into conversation with Reformed and Puritan theology, asking how the church’s confidence in Scripture informs its teaching and spiritual practices.</p></section><section class="topic-section" id="church"><p class="eyebrow">03 · The church’s shared life</p><h2>Belonging carries responsibility.</h2><p>Scripture addresses a people whose common life includes fellowship, worship, mutual care, and discipline. These practices belong within theological reflection on redemption and the identity of the church.</p><p>The research examines how the biblical language of a gathered people can sharpen our understanding of the church’s confession and conduct.</p></section></div></div><section class="section wrap" id="publications"><p class="eyebrow">Publication catalog</p><h2>Published work</h2><div class="catalog-tools"><div class="field"><label for="article-search">Search title, topic, or publication</label><input id="article-search" type="search" placeholder="Try Passover, assurance, or Themelios"></div><div class="field"><label for="article-topic">Filter by topic</label><select id="article-topic"><option value="">All topics</option>'''
for t in ['Passover','Church','1 Peter','1 John','Formation','Micah','Assurance']:body+=f'<option>{t}</option>'
body+='</select></div></div><p class="results-status" id="results-status" aria-live="polite">4 of 4 publications</p>'+''.join(pub(p) for p in PUBLICATIONS)+'<p class="empty" id="empty-results" hidden>No publications match these terms. Try another topic or clear the search.</p><p class="note">Articles open at their publishers, where the full texts, citations, and publication details are maintained.</p></section>'
page('Research & publications','Published scholarship and essays on Passover, fellowship, Scripture, and spiritual formation.',body,'research')

BOOKS=[('Light Upon Light','An Ascending Journey Through the Wisdom of 1 John','A sustained reading of 1 John for pastors, teachers, and readers seeking deeper assurance, love, and faithful living.','light-upon-light'),('Dirge & Dawn','A Holy Week narrative','A narrative journey through Jesus’ passion and resurrection, moving from the sorrow of Holy Week toward the hope of Easter.','dirge-and-dawn'),('Mercy Upon Mercy','A study through Micah','A commentary project attending to judgment, covenant faithfulness, and the mercy that shapes Micah’s closing vision.','mercy-upon-mercy'),('Grace Upon Grace','A study through 1 Peter','A commentary project exploring hope, holiness, suffering, and the shared life of God’s people in 1 Peter.','grace-upon-grace')]
body=intro('Books & teaching','Work at greater length.','Commentary and narrative projects written to bring careful biblical interpretation into the worship and life of the church.')+'<section class="wrap">'
for i,(title,sub,desc,slug) in enumerate(BOOKS,1):body+=f'<article class="book-entry"><span class="num">0{i}</span><div><h2>{title}</h2><p class="book-subtitle">{sub}</p><p>{desc}</p>{link("About this project",f"/books/{slug}/")}</div><span class="pill">Book project</span></article>'
body+='<p class="note">These are writing projects. Publication and purchase details will be added when available.</p></section>'
page('Books & teaching','Light Upon Light, Dirge & Dawn, and commentary projects by Craig R. Fredrickson.',body,'books')
for title,sub,desc,slug in BOOKS:
    extra='''<h2>An ascending way of reading</h2><p>John returns to light, love, truth, obedience, and assurance throughout his letter. This project follows those recurring themes, inviting readers to revisit the text with growing understanding.</p><p>Reflection prompts connect observation and interpretation with prayer, conversation, and the practice of Christian fellowship.</p><div class="actions"><a class="button" href="/resources/walking-in-the-light/">Try a 1 John discussion guide</a><a class="text-link" href="/essays/">Read related essays</a></div>''' if slug=='light-upon-light' else '<h2>From reading to reflection</h2><p>This project joins close attention to Scripture with questions for Christian faith and life. It is part of Craig’s ongoing work in biblical exposition and spiritual formation.</p><div class="actions"><a class="button" href="/contact/">Ask about this project</a><a class="text-link" href="/books/">All book projects</a></div>'
    page(title,sub,intro('Book project',title,sub)+f'<div class="content-grid wrap"><aside class="side-note"><p class="eyebrow">Craig R. Fredrickson</p><p>Writing project</p></aside><div class="prose"><p>{desc}</p>{extra}<p class="note">A publication date has not been announced.</p></div></div>',f'books/{slug}')

